        'memo.intro': {
            en: 'Sticky snippets live inside this browser (local storage). On the dashboard, the same cards show as draggable mini notes; new ones appear along the bottom so tiles stay easy to see — drag them anywhere. Tap a memo here to edit — AI polishing uses the same secure Edge lane as Outreach when deployed. No clinical jargon required; omit secrets from AI prompts where possible.',
            'zh-CN': '备忘片段保存在本浏览器（本地存储）。控制台上相同卡片显示为可拖动小便签；新便签默认排在底部以免遮挡卡片——可拖到任意位置。在此点按备忘即可编辑——若已部署，AI 润色与外展模块使用相同的安全 Edge 通道。无需临床术语；请勿在 AI 提示中包含机密。',
            'zh-Hant': '備忘片段儲存在本瀏覽器（本機儲存）。控制台上相同卡片顯示為可拖動小便簽；新便簽預設排在底部以免遮擋卡片——可拖到任意位置。在此點按備忘即可編輯——若已部署，AI 潤色與外展模組使用相同的安全 Edge 通道。無需臨床術語；請勿在 AI 提示中包含機密。'
        },
