            'zh-CN': '存储策略阻止上传。<br><br>在 <strong>Supabase SQL Editor</strong> 中运行：<br><code>CREATE POLICY "xrays_upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = \'{BUCKET}\');</code>',
            'zh-Hant': '儲存策略阻止上載。<br><br>在 <strong>Supabase SQL Editor</strong> 中執行：<br><code>CREATE POLICY "xrays_upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = \'{BUCKET}\');</code>'
