        'ai.demo.letter.dear': { en: 'Dear {NAME},', 'zh-CN': '亲爱的 {NAME}：', 'zh-Hant': '親愛的 {NAME}：' },
        'ai.demo.letter.happyBirth': { en: 'Happy Birthday from {CLINIC}!', 'zh-CN': '{CLINIC} 祝您生日快乐！', 'zh-Hant': '{CLINIC} 祝您生日快樂！' },
        'ai.demo.letter.withCare': { en: 'With care,', 'zh-CN': '此致', 'zh-Hant': '此致' },
        'ai.demo.letter.kindRegards': { en: 'Kind regards,', 'zh-CN': '敬祝', 'zh-Hant': '敬祝' },
        'ai.demo.email.subjectBirth': { en: 'Birthday greetings', 'zh-CN': '生日问候', 'zh-Hant': '生日問候' },
        'ai.demo.email.subjectRecall': { en: 'Dental recall reminder', 'zh-CN': '牙科复诊提醒', 'zh-Hant': '牙科覆診提醒' },
        'ai.demo.birth.warmProf.0': { en: 'Wishing you a wonderful birthday filled with smiles.', 'zh-CN': '祝您生日快乐，笑容满面。', 'zh-Hant': '祝您生日快樂，笑容滿面。' },
        'ai.demo.birth.warmProf.1': { en: 'We hope this year keeps you confident and comfortable every day.', 'zh-CN': '愿新的一年每天都自信舒适。', 'zh-Hant': '願新的一年每天都自信舒適。' },
        'ai.demo.birth.warmProf.2': { en: 'Thank you for trusting us with your dental health — warm regards from everyone here.', 'zh-CN': '感谢您信任我们的牙科护理——全体同仁致意。', 'zh-Hant': '感謝您信任我們的牙科護理——全體同仁致意。' },
        'ai.demo.birth.festive.0': { en: '🎉 Happy Birthday! Celebrate with laughter and treats.', 'zh-CN': '🎉 生日快乐！愿欢笑与甜蜜相伴。', 'zh-Hant': '🎉 生日快樂！願歡笑與甜蜜相伴。' },
        'ai.demo.birth.festive.1': { en: 'We’re cheering for your healthiest, happiest smile year yet.', 'zh-CN': '我们为您最健康、最灿烂的笑容加油。', 'zh-Hant': '我們為您最健康、最燦爛的笑容加油。' },
        'ai.demo.birth.minimal.0': { en: 'Happy birthday from all of us.', 'zh-CN': '我们全体祝您生日快乐。', 'zh-Hant': '我們全體祝您生日快樂。' },
        'ai.demo.birth.minimal.1': { en: 'Warm wishes — here anytime for preventive care bookings.', 'zh-CN': '温馨祝福——随时欢迎预约预防护理。', 'zh-Hant': '溫馨祝福——隨時歡迎預約預防護理。' },
        'ai.demo.recall.checkup.warmProf.0': { en: 'Preventive hygiene helps protect enamel long term.', 'zh-CN': '预防性洁牙有助长期保护牙釉质。', 'zh-Hant': '預防性潔牙有助長期保護牙釉質。' },
        'ai.demo.recall.checkup.warmProf.1': { en: 'We can whisper-book a calm hygienist slot.', 'zh-CN': '我们可为您悄悄预留较安静的洁牙时段。', 'zh-Hant': '我們可為您悄悄預留較安靜的潔牙時段。' },
        'ai.demo.recall.checkup.gentle.0': { en: 'Friendly nudge for upcoming preventive timing.', 'zh-CN': '温馨提醒即将到来的预防护理时间。', 'zh-Hant': '溫馨提醒即將到來的預防護理時間。' },
        'ai.demo.recall.checkup.gentle.1': { en: 'No pressure — reply anytime.', 'zh-CN': '不设压力——随时回复即可。', 'zh-Hant': '不設壓力——隨時回覆即可。' },
        'ai.demo.recall.checkup.concise.0': { en: 'Time for preventive care.', 'zh-CN': '是时候做预防护理了。', 'zh-Hant': '是時候做預防護理了。' },
        'ai.demo.recall.checkup.concise.1': { en: 'SMS us for quick booking.', 'zh-CN': '短信我们快速预约。', 'zh-Hant': '短訊我們快速預約。' },
        'ai.demo.recall.incompleteTx.warmProf.0': { en: 'Thoughtful update on unfinished treatment—we’ll finish steps patiently.', 'zh-CN': '关于未完成治疗的贴心跟进——我们将耐心完成每一步。', 'zh-Hant': '關於未完成治療的貼心跟進——我們將耐心完成每一步。' },
        'ai.demo.recall.incompleteTx.warmProf.1': { en: 'Whenever ready.', 'zh-CN': '您准备好时随时联系。', 'zh-Hant': '您準備好時隨時聯絡。' },
        'ai.demo.recall.incompleteTx.gentle.0': { en: 'Continuing care avoids small issues layering—no hurry.', 'zh-CN': '持续护理可避免小问题累积——不必着急。', 'zh-Hant': '持續護理可避免小問題累積——不必著急。' },
